async function snapshot(excludeActivity=false){const d:Record<string,unknown>={};for(const {tablename:t} of await h.observer`select tablename from pg_tables where schemaname='crm_private' order by tablename`)if(!(excludeActivity&&t==='identification_epochs'))d[t]=(await h.observer.unsafe(`select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]') d from crm_private.${t} x`))[0]!.d;return d;}
async function noEffect(action:()=>Promise<unknown>){const old=await snapshot();await assert.rejects(action());assert.deepEqual(await snapshot(),old);}
function counts(v:any){const s=v.booking.detail.services;return {rafting:s[0].contributions.reduce((n:number,c:any)=>n+c.attendees,0),dinner:s[1].contributions.reduce((n:number,c:any)=>n+c.attendees,0),nights:s[2].nights.map((night:any)=>({date:night.date,people:s[2].contributions.filter((c:any)=>night.contributionIds.includes(c.id)).reduce((n:number,c:any)=>n+c.attendees,0)})),nominal:v.booking.detail.participants.length,assignments:v.booking.detail.assignments.length};}
const scoped=(x:X,i=0)=>({kind:'service',id:x.q.detail.services[i]!.id});
