test('H6003 F01 AC017/019 actual T03 exact10+2 rafting10 dinner12 nights12/10 four partial names with source readback',async t=>{const x=await integratedFixture(h),v=await x.current();assert.deepEqual(counts(v),{rafting:10,dinner:12,nights:[{date:'2026-10-20',people:12},{date:'2026-10-21',people:10}],nominal:4,assignments:4});assert.equal(v.booking.detail.services.length,3);assert.equal((await h.observer`select count(*)::int n from crm_private.b04_bookings where opportunity_id=${x.q.opportunityId}::uuid`)[0]!.n,1);const origins=await h.observer`select c.source_snapshot,m.snapshot modality from crm_private.b04_contributions c join crm_private.b04_modalities m on m.booking_id=c.booking_id and m.modality_id=c.modality_id where c.booking_id=${x.q.bookingId}::uuid`;assert.equal(origins.length,6);assert.ok(origins.every(r=>r.source_snapshot&&r.modality));assert.equal(v.booking.detail.services[2].variant,null);assert.equal(JSON.stringify(v.booking.detail).includes('room'),false);t.diagnostic(JSON.stringify({bookingId:x.q.bookingId,counts:counts(v),originContributions:origins.length}));});
test('H6003 F02 T03 rejects global overwrite, nominal duplicate or unrelated night/line before any Booking',async()=>{const x=await integratedFixture(h,false);for(const mutate of [(d:any)=>d.services[0].contributions[0].attendees=12,(d:any)=>d.participants.push({...d.participants[0],id:uid()}),(d:any)=>d.services[2].nights[1].contributionIds.push(d.services[0].contributions[0].id),(d:any)=>d.services[0].contributions[0].lineId=uid()]){const detail=structuredClone(x.q.detail);mutate(detail);const q={...x.q,detail,evidenceId:await x.quantities.detailProof(detail)};await noEffect(async()=>h.booking.apply(await h.auth(),write,q));}await h.booking.apply(await h.auth(),write,x.q);assert.equal(counts(await x.current()).nominal,4);});
test('H6003 F03 AC018 group12to14 preserves rafting confirmed10 and nights; dinner review scoped and exact application',async t=>{const x=await integratedFixture(h),f=await x.confirm(),coverage={...f.coverage,quantity:'10'};await f.apply(await f.register({coverage}));await f.apply(await f.evaluate({coverage}));assert.equal((await f.assess())!.usable,true);const before=await x.current(),m=await exactChange(h,x,{kind:'booking',id:x.q.bookingId},{estimated:14},['estimated']);await m.run(await m.apply());const group=await x.current();assert.deepEqual(counts(group),counts(before));assert.equal((await f.assess())!.usable,true);assert.equal(group.booking.detail.aggregate.estimated,14);const dinner=await x.confirm(1),dc={...dinner.coverage,quantity:'12'};await dinner.apply(await dinner.register({coverage:dc}));await dinner.apply(await dinner.evaluate({coverage:dc}));const n=await x.change(1);await n.run(await n.request([{id:n.partId,scope:scoped(x,1),expectedScopeRevision:1,desired:{date:'2026-10-22'},aspects:['date','capacity','conditions'],dependencies:[]}]));const unchanged=await x.current();await n.run(await n.evaluate());assert.deepEqual(counts(await x.current()),counts(unchanged));assert.equal((await x.current()).booking.detail.services[1].date,'2026-10-20');assert.equal((await dinner.assess())!.usable,false);assert.equal((await f.assess())!.usable,true);await n.run(await n.approve());await n.run(await n.apply());const after=await x.current();assert.equal(after.booking.detail.services[1].date,'2026-10-22');assert.deepEqual(after.booking.detail.services[0],group.booking.detail.services[0]);assert.deepEqual(after.booking.detail.services[2],group.booking.detail.services[2]);assert.deepEqual(after.booking.accepted_detail,before.booking.detail);assert.equal((await n.see())!.parts[0]!.before!==undefined,true);t.diagnostic(JSON.stringify({counts:counts(after),globalEstimated:after.booking.detail.aggregate.estimated,dinnerDate:after.booking.detail.services[1].date,raftingStillUsable:(await f.assess())!.usable}));});
test('H6003 F04 AC019 authorized night2 change preserves night1 and four names, aggregate and accepted history',async t=>{const x=await integratedFixture(h),before=await x.current(),house=x.q.detail.services[2]!,night=house.nights[1]!,m=await exactChange(h,x,{kind:'night',id:night.id,serviceId:house.id},{date:'2026-10-22'},['date']);await m.run(await m.apply());const after=await x.current();assert.deepEqual(counts(after),{rafting:10,dinner:12,nights:[{date:'2026-10-20',people:12},{date:'2026-10-22',people:10}],nominal:4,assignments:4});assert.deepEqual({id:after.booking.detail.services[2].nights[0].id,date:after.booking.detail.services[2].nights[0].date,contributionIds:after.booking.detail.services[2].nights[0].contributionIds},before.booking.detail.services[2].nights[0]);assert.equal(after.booking.detail.services[2].nights[0].revision,1);assert.equal(after.booking.detail.services[2].nights[0].cancelled,false);assert.deepEqual(Object.keys(after.booking.detail.services[2].nights[0]).sort(),['id','date','contributionIds','revision','cancelled'].sort());assert.deepEqual(after.booking.detail.participants,before.booking.detail.participants);assert.deepEqual(after.booking.detail.assignments,before.booking.detail.assignments);assert.deepEqual(after.booking.accepted_detail,before.booking.detail);assert.equal((await m.see())!.progress,'Aplicada');t.diagnostic(JSON.stringify(counts(after)));});
test('H6003 F05 AC024 confirmed18 is preserved when tentative16/date arrives; time-only ratification leaves quantity/capacity/conditions pending and Task',async t=>{const x=await integratedFixture(h),c=x.q.detail.services[0]!.contributions[0]!,scope={kind:'contribution',id:c.id,serviceId:x.q.detail.services[0]!.id},m=await exactChange(h,x,scope,{attendees:18,certainty:'confirmed'},['quantity','capacity']);await m.run(await m.apply());const n=await x.change(),before=await x.current();assert.equal(before.booking.detail.services[0].contributions[0].attendees,18);const c18=await x.confirm(),coverage18={...c18.coverage,quantity:'18'};await c18.apply(await c18.register({coverage:coverage18}));await c18.apply(await c18.evaluate({coverage:coverage18}));assert.equal((await c18.assess())!.usable,true);const confirmed18=(await c18.state())!.fact;await n.run(await n.request([{id:n.partId,scope,expectedScopeRevision:2,desired:{attendees:16,certainty:'estimated'},aspects:['quantity','capacity','conditions','time'],dependencies:[]}]));await n.run(await n.evaluate());assert.deepEqual(counts(await x.current()),counts(before));assert.deepEqual((await x.current()).booking.accepted_detail,before.booking.accepted_detail);await n.run(await ratify(h,n,['time']));assert.deepEqual(((await n.see())!.parts[0] as any).review.aspects,['quantity','capacity','conditions']);assert.equal(((await n.see())!.parts[0] as any).review.pending,true);assert.deepEqual((await c18.state())!.fact,confirmed18);assert.equal((await c18.assess())!.usable,false);assert.deepEqual(counts(await x.current()),counts(before));assert.deepEqual((await x.current()).booking.accepted_detail,before.booking.accepted_detail);const tasks=await h.observer`select to_jsonb(t) d from crm_private.b07_pending_tasks t where identity->>'contextId'=${x.q.bookingId}`;assert.ok(tasks.length>0);t.diagnostic(JSON.stringify({confirmedBefore:18,actualAfter:(await x.current()).booking.detail.services[0].contributions[0].attendees,pendingAspects:((await n.see())!.parts[0] as any).review.aspects,tasks:tasks.length}));});
test('H6003 F06 AC038 gratuity150 on A10x150 B5x120 keeps15 attendees14payers and external debts; missing modality/noneligible guarded',async t=>{for(const mode of ['eligible','missing-modality','wrong-audience'] as const){const f=await ownEconomicsFixture(h),external=await economyBookingFixture(h,'total',true,'external');await h.booking.apply(await h.auth(),write,external.q);const provider=await h.cat('provider',{name:'H6003 SYNTHETIC separate external debt'}),invoiceId=uid(),need={action:'need' as const,operationId:uid(),invoiceId,bookingId:external.q.bookingId,expectedRevision:0,sourceRef:'H6003 SYNTHETIC external debt source',reason:'H6003 SYNTHETIC debt no real fiscal effect',at:f.at,evidenceId:uid(),basis:{providerRevisionId:provider.revision,recipientId:external.f.accepterId,amount:'500.00',serviceIds:external.detail.services.map(s=>s.id),sourceRef:'H6003 SYNTHETIC owed external500',version:'1'}};const proof=h.req('evidence',{claim:'invoice:need:'+await f.digest(Object.fromEntries(Object.entries(need).filter(([k])=>!['operationId','evidenceId'].includes(k)))),coverage:invoiceId,certainty:'reviewed',source_kind:'manual'},invoiceId,'other');await h.evidence.apply(await h.auth(),write,{...proof,coverage:invoiceId,occurredAt:f.at});await h.invoices.apply(await h.auth(),write,{...need,evidenceId:proof.targetId});const q=await f.command({bookingId:external.q.bookingId});for(const c of [...q.input.fees,...q.input.costs])Object.assign(c,{serviceId:external.detail.services[0]!.id});const input=promotion(mode==='missing-modality'?null:external.f.mid);Object.assign(q.input,{promotion:{...input,revisionId:f.promo.revision,...(mode==='wrong-audience'?{audience:'other'}:{})}});const before=(await h.observer`select to_jsonb(b) d from crm_private.b04_bookings b where booking_id=${external.q.bookingId}::uuid`)[0]!.d,debts=await h.observer`select to_jsonb(i) d from crm_private.b05_provider_invoices i where booking_id=${external.q.bookingId}::uuid`;assert.equal(debts.length,1);const r=await h.ownEconomics.apply(await h.auth(),write,await f.attest(q)),p=r.result.computed.promotion!;if(mode==='eligible'){assert.equal(p.amount,'150.00');assert.equal(p.realAttendees,15);assert.equal(p.payers,14);}else if(mode==='missing-modality'){assert.equal(p.amount,null);assert.equal(p.status,'pending');}else{assert.equal(p.amount,null);assert.equal(p.status,'ineligible');}assert.deepEqual((await h.observer`select to_jsonb(b) d from crm_private.b04_bookings b where booking_id=${external.q.bookingId}::uuid`)[0]!.d,before);assert.deepEqual(await h.observer`select to_jsonb(i) d from crm_private.b05_provider_invoices i where booking_id=${external.q.bookingId}::uuid`,debts);assert.equal(external.detail.services.reduce((n,s)=>n+s.contributions.reduce((n,c)=>n+c.attendees,0),0),15);t.diagnostic(JSON.stringify({mode,promotion:p,bookingUnchanged:true,providerDebtsUnchanged:true}));}});
test('H6003 F07 AC043 actual time-only20 retains civil interval; date22 revises exact scope and historical evaluation remains',async t=>{const x=await integratedFixture(h),m=await x.change(),scope=scoped(x),reference={scope,zone:'Europe/Madrid',sourceRef:'H6003 SYNTHETIC exact date source',version:'V1',basis:'default',referenceDate:'2026-10-20'};await m.run(await m.request([{id:m.partId,scope,expectedScopeRevision:1,desired:{schedule:{requested:'11:00',alternatives:['11:00','12:30'],final:'12:30:00+02:00',sourceRef:'H6003 SYNTHETIC exact time'}},aspects:['time'],dependencies:[]}]));const q=await m.evaluate();await m.run(await m.command('evaluate',{...q.data,temporal:[reference]},{at:'2026-10-13T23:59:59+02:00'}));assert.equal((await m.see() as any).evaluation.civilEvaluations[0].daysBefore,7);await m.run(await m.approve());await m.run(await m.apply());const first=await m.see() as any;assert.equal(first.currentCivilEvaluations[0].referenceDate,'2026-10-20');const n=await x.change();await n.run(await n.request([{id:n.partId,scope,expectedScopeRevision:2,desired:{date:'2026-10-22'},aspects:['date'],dependencies:[]}]));const nq=await n.evaluate();await n.run(await n.command('evaluate',{...nq.data,temporal:[reference]},{at:'2026-10-17T23:59:59+02:00'}));assert.equal((await n.see() as any).evaluation.civilEvaluations[0].daysBefore,3);await n.run(await n.approve());await n.run(await n.apply());assert.equal((await n.see() as any).currentCivilEvaluations[0].referenceDate,'2026-10-22');assert.equal((await m.see() as any).evaluation.civilEvaluations[0].daysBefore,7);assert.equal((await m.see() as any).evaluation.civilEvaluations[0].referenceDate,'2026-10-20');assert.equal((await x.current()).booking.detail.services[1].date,'2026-10-20');t.diagnostic(JSON.stringify({historicalDays:7,beforeReference:'2026-10-20',currentReference:'2026-10-22',siblingDate:'2026-10-20'}));});
test('H6003 F08 AC043 final-figure service Tasks persist hour-invariant day and date22 scoped revision without changing completed historical Task',async()=>{const x=await integratedFixture(h),tasks=new H5001TaskAdapter(h.runtime,h.f1,h.f2),zone=zoneEvidence('Europe/Madrid','H6003 SYNTHETIC explicit zone','1');const ref=(id:string,date:string,version='1')=>civilReference({scope:'service',scopeId:id},localDate(date),zone,'H6003 SYNTHETIC scoped date',version);const event=(id:string,date:string,version='1')=>({cause:'final_participants' as const,causeId:id,contextKind:'booking',contextId:x.q.bookingId,scopeRef:id,sourceRef:'H6003 SYNTHETIC approved final figure',sourceVersion:version,finalParticipants:{reference:ref(id,date,version)}});const need=approvedTaskNeeds(event(x.q.detail.services[0]!.id,'2026-10-20'))[0]!,other=approvedTaskNeeds(event(x.q.detail.services[1]!.id,'2026-10-20'))[0]!;const cmd=(n:typeof need):TaskCommand=>({action:'receive',operationId:uid(),taskId:uid(),expectedRevision:0,identity:n.identity,material:n.material,reason:n.reason});const a=cmd(need),b=cmd(other);await tasks.apply(await h.auth(),write,a);await tasks.apply(await h.auth(),write,b);const see=async(q:TaskCommand)=>tasks.read(await h.auth(),read,q.taskId,'booking',x.q.bookingId);const sb=await see(b),initial=await see(a);await tasks.apply(await h.auth(),write,{...a,operationId:uid(),taskId:uid()});assert.deepEqual((await see(a))!.material.deadline,initial!.material.deadline);const newer=approvedTaskNeeds(event(x.q.detail.services[0]!.id,'2026-10-22','2'))[0]!;await tasks.apply(await h.auth(),write,{...a,action:'update',operationId:uid(),expectedRevision:1,material:newer.material});assert.equal(((await see(a))!.material.deadline as any).reference.date,'2026-10-22');assert.deepEqual(await see(b),sb);const historic=await h.observer`select after_state from crm_private.b07_history where subject_id=${a.taskId}::uuid order by recorded_at`;assert.equal((historic[0]!.after_state as any).material.deadline.reference.date,'2026-10-20');await tasks.transition(await h.auth(),write,{action:'complete',operationId:uid(),taskId:a.taskId,expectedRevision:2,reason:'H6003 SYNTHETIC completed review',result:'H6003 completed evidence',references:['H6003 synthetic figure']});const completed=await see(a);const later=approvedTaskNeeds({...event(x.q.detail.services[1]!.id,'2026-10-20','2'),finalParticipants:{reference:ref(x.q.detail.services[1]!.id,'2026-10-20','2'),daysBefore:3}})[0]!;await tasks.apply(await h.auth(),write,{...b,action:'update',operationId:uid(),expectedRevision:1,material:later.material});assert.deepEqual(await see(a),completed);});
test('H6003 F09 T04 missing approval/evidence/stale scope/foreign root denied with exact original history',async()=>{const x=await integratedFixture(h),m=await x.change();await m.run(await m.request());await m.run(await m.evaluate());const missingApproval=await m.command('apply',{partIds:[m.partId],approvalRevision:1});await noEffect(()=>m.run(missingApproval));const approve=await m.approve(),proofs=approve.data.proofs as any;for(const field of ['client','provider','constraints']){const p={...proofs[m.partId]};delete p[field];const q=await m.attest({...approve,data:{...approve.data,proofs:{[m.partId]:p}}});await noEffect(()=>m.run(q));}await m.run(approve);const q=await m.apply();await noEffect(()=>m.run({...q,evidenceId:uid()}));const b=await integratedFixture(h);const foreign=await m.attest({...q,bookingId:b.q.bookingId});await noEffect(()=>m.run(foreign));const v=await x.current();await m.run(q);const conflict=await m.attest({...q,operationId:uid(),reason:'H6003 different material'});await noEffect(()=>m.run(conflict));assert.deepEqual((await x.current()).booking.accepted_detail,v.booking.detail);});
test('H6003 F10 T04 late COMMIT failure rolls effect/history/result/task back; retry and exact replay once',async()=>{const x=await integratedFixture(h),m=await exactChange(h,x,scoped(x),{date:'2026-10-22'},['date']),q=await m.apply(),before=await snapshot();await h.admin.unsafe(`create function crm_private.h6003_fault() returns trigger language plpgsql as $$begin raise exception 'H6003_SYNTHETIC_COMMIT_FAULT';end$$;create constraint trigger h6003_fault after insert on crm_private.b04_operational_versions deferrable initially deferred for each row execute function crm_private.h6003_fault()`);try{await assert.rejects(m.run(q));assert.deepEqual(await snapshot(),before);}finally{await h.admin.unsafe('drop trigger h6003_fault on crm_private.b04_operational_versions;drop function crm_private.h6003_fault()');}await m.run(q);const after=await snapshot(true);assert.equal((await m.run(q)).replayed,true);assert.deepEqual(await snapshot(true),after);assert.equal((await x.current()).booking.detail.services[0].date,'2026-10-22');});
test('H6003 F11 T04 lost response after COMMIT recovers same operation result, no double versions',async()=>{const x=await integratedFixture(h),m=await exactChange(h,x,scoped(x),{date:'2026-10-22'},['date']),q=await m.apply();const dropped={begin:async(...args:any[])=>{await (h.runtime.begin as any)(...args);throw Error('H6003_LOST_RESPONSE_AFTER_COMMIT');}};const adapter=new H4011ModificationAdapter(dropped as never,h.f1,h.f2);await assert.rejects(adapter.apply(await h.auth(),write,q));const before=await snapshot(true);assert.equal((await m.run(q)).replayed,true);assert.deepEqual(await snapshot(true),before);assert.equal((await m.see())!.progress,'Aplicada');});
test('H6003 F12 T04 overlapping changes same night both orders two sessions one winner preserve sibling scopes',async t=>{const first=await verifyAuth({verify:async()=>({subject:h.subject,passwordVerified:true,mfaVerified:true})},uid()),sessionId=(await new H0005PostgresAdapter(h.runtime,h.f1,h.f2).establish(first)).sessionId,second=await verifyAuth({verify:async()=>({subject:h.subject,sessionId,passwordVerified:true,mfaVerified:true})},uid());for(const reverse of [false,true]){const x=await integratedFixture(h),house=x.q.detail.services[2]!,scope={kind:'night',id:house.nights[1]!.id,serviceId:house.id},a=await exactChange(h,x,scope,{date:'2026-10-22'},['date']),b=await exactChange(h,x,scope,{date:'2026-10-23'},['date']),aq=await a.apply(),bq=await b.apply(),before=await x.current();let ready!:()=>void,unlock!:()=>void;const locked=new Promise<void>(r=>ready=r),gate=new Promise<void>(r=>unlock=r),hold=h.admin.begin(async tx=>{await tx`select booking_id from crm_private.b04_bookings where booking_id=${x.q.bookingId}::uuid for update`;ready();await gate;});await locked;const auth=await h.auth(),actions=[()=>h.modifications.apply(auth,write,aq),()=>h.modifications.apply(second,write,bq)];if(reverse)actions.reverse();const pending=Promise.allSettled(actions.map(f=>f())),monitor=h.connect('h2_bootstrap');let blocked=0;try{for(let i=0;i<100;i++){blocked=(await monitor`select count(*)::int n from pg_stat_activity where datname=current_database() and usename='crm_h0_runtime' and wait_event_type='Lock'`)[0]!.n;if(blocked>=2)break;await new Promise(r=>setTimeout(r,10));}assert.ok(blocked>=2);}finally{unlock();await hold;}const result=await pending;assert.equal(result.filter(r=>r.status==='fulfilled').length,1);const current=await x.current();assert.deepEqual({id:current.booking.detail.services[2].nights[0].id,date:current.booking.detail.services[2].nights[0].date,contributionIds:current.booking.detail.services[2].nights[0].contributionIds},before.booking.detail.services[2].nights[0]);assert.equal(current.booking.detail.services[2].nights[0].revision,1);assert.equal(current.booking.detail.services[2].nights[0].cancelled,false);assert.deepEqual(Object.keys(current.booking.detail.services[2].nights[0]).sort(),['id','date','contributionIds','revision','cancelled'].sort());assert.deepEqual(current.booking.detail.participants,before.booking.detail.participants);assert.equal(counts(current).nights[1]!.people,10);t.diagnostic(JSON.stringify({reverse,blockedSessions:blocked,winners:1,currentNight2:counts(current).nights[1]}));}});
test('H6003 F13 actor/context/SQL roles/direct historical edits/replayed result reauthorization enforced',async()=>{const x=await integratedFixture(h),m=await exactChange(h,x,scoped(x),{date:'2026-10-22'},['date']),q=await m.apply();await m.run(q);const old=await snapshot();await assert.rejects(h.modifications.apply({} as never,write,q));await assert.rejects(h.modifications.apply({...await h.auth()} as never,write,q));for(const role of ['crm_h0_runtime','anon','authenticated']){const c=h.connect(role);await assert.rejects(c`select * from crm_private.b04_contributions`);await assert.rejects(c`update crm_private.b04_nights set night_date='2026-10-23'`);await assert.rejects(c`delete from crm_private.b06_modification_revisions`);}assert.deepEqual(await snapshot(),old);await h.migration`update crm_private.crm_actors set enabled=false where actor_id=${h.actorId}::uuid`;try{await assert.rejects(m.run(q));await assert.rejects(h.modifications.read(await h.auth(),read,m.modificationId,m.bookingId));}finally{await h.migration`update crm_private.crm_actors set enabled=true where actor_id=${h.actorId}::uuid`;}const y=await integratedFixture(h);assert.equal(await h.modifications.read(await h.auth(),read,m.modificationId,y.q.bookingId),null);assert.ok(await h.modifications.read(await h.auth(),read,m.modificationId,m.bookingId));});
test('H6003 F14 P09 actual price/capacity/summary outputs retain service/night grain and approved fixed units',async t=>{const x=await integratedFixture(h),internal=await h.proposal.read(await h.auth(),read,x.q.proposalId,'internal',x.q.versionId) as any,commercial=await h.proposal.read(await h.auth(),read,x.q.proposalId,'commercial',x.q.versionId) as any[];const e=internal.economics as any[];assert.deepEqual(e.map(z=>z.calculated).sort(),['360.00','900.00']);assert.ok(e.every(z=>z.components.every((c:any)=>c.quantity==='1'&&c.amount==='900.00')));assert.deepEqual(e.map(z=>z.finalCalculation.output.amount).sort(),['1000.10','200.02']);assert.deepEqual(commercial.map(z=>({participants:z.participants,final:z.finalPersonPrice})).sort((a,b)=>a.participants-b.participants),[{participants:2,final:'100.01'},{participants:10,final:'100.01'}]);const conf=await x.confirm(2),house=x.q.detail.services[2]!,a=house.nights[0]!,b=house.nights[1]!,basis=conf.coverage.commercialBasis,coverage={...conf.coverage,nightId:a.id,date:a.date,quantity:'12',commercialBasis:{...basis,contributions:basis.contributions.filter(c=>a.contributionIds.includes(c.id as string))}};await conf.apply(await conf.register({coverage}));await conf.apply(await conf.evaluate({coverage}));assert.equal((await conf.assess())!.usable,true);await assert.rejects(conf.apply(await conf.evaluate({coverage:{...coverage,nightId:b.id,date:b.date,quantity:'10'}})));const second=await x.confirm(2),c2={...second.coverage,nightId:b.id,date:b.date,quantity:'10',commercialBasis:{...second.coverage.commercialBasis,contributions:second.coverage.commercialBasis.contributions.filter(c=>b.contributionIds.includes(c.id as string))}};await second.apply(await second.register({coverage:c2}));await second.apply(await second.evaluate({coverage:c2}));assert.equal((await second.assess())!.usable,true);const p=await preparationCommands(h,x.q.bookingId);await p.run(await p.command([await p.classify(x.q.detail.services[0]!.id),await p.classify(x.q.detail.services[1]!.id),await p.classify(house.id,a.id),await p.classify(house.id,b.id)]));const prep=(await p.read())!,nights=prep.coverage.filter(z=>(z.scope as any).nightId);assert.deepEqual(nights.map(z=>(z.scope as any).quantity).sort((a,b)=>b-a),[12,10]);const reader=new H5011ProjectionAdapter(h.runtime,h.f1,h.f2),projection=await reader.read(await h.auth(),read,{contextKind:'booking',contextId:x.q.bookingId,destination:'customer',surface:'document'});assert.deepEqual(projection!.entries.map((z:any)=>({participants:z.participants,final:z.finalPersonPrice})).sort((a,b)=>a.participants-b.participants),[{participants:2,final:'100.01'},{participants:10,final:'100.01'}]);t.diagnostic(JSON.stringify({calculated:e.map(z=>z.calculated),finalTotals:e.map(z=>z.finalCalculation.output.amount),fixedLineAmounts:e.flatMap(z=>z.components.map((c:any)=>c.amount)),nightSummary:nights.map(z=>z.scope),externalSummary:projection!.entries}));});
